// Package lru implements a fixed-capacity least-recently-used cache with
// O(1) expected time for every operation.
//
// Entries live in a slice-backed pool and are linked into a doubly linked
// recency list by 32-bit index, which keeps nodes compact and avoids a heap
// allocation per entry. Index 0 is a sentinel acting as the list head.
package lru

const sentinel int32 = 0

type node struct {
	key   string
	value string
	prev  int32 // towards most recently used
	next  int32 // towards least recently used
}

// Cache maps string keys to string values, holding at most Capacity keys.
// The zero value is not usable; create caches with New.
type Cache struct {
	nodes    []node           // nodes[0] is the list sentinel
	index    map[string]int32 // key -> node index
	free     []int32          // recycled node indices
	capacity int
}

// New returns a cache that holds at most capacity keys. sizeHint is an
// optional estimate of how many keys will be live at once; storage for
// min(capacity, sizeHint) entries is preallocated. A non-positive sizeHint
// means no estimate. New panics if capacity is not positive.
func New(capacity, sizeHint int) *Cache {
	if capacity <= 0 {
		panic("lru: capacity must be positive")
	}
	prealloc := capacity
	if sizeHint > 0 && sizeHint < prealloc {
		prealloc = sizeHint
	}
	c := &Cache{
		nodes:    make([]node, 1, prealloc+1),
		index:    make(map[string]int32, prealloc),
		capacity: capacity,
	}
	return c
}

// Len reports the number of keys currently held.
func (c *Cache) Len() int { return len(c.index) }

// Capacity reports the maximum number of keys the cache holds.
func (c *Cache) Capacity() int { return c.capacity }

// Set inserts or overwrites key; it becomes the most recently used. If the
// cache would exceed its capacity, the least recently used key is evicted.
func (c *Cache) Set(key, value string) {
	if i, ok := c.index[key]; ok {
		c.nodes[i].value = value
		c.moveToFront(i)
		return
	}

	// Evicting before inserting is observably identical to inserting and
	// then evicting, and keeps the pool bounded by the capacity.
	if len(c.index) >= c.capacity {
		c.remove(c.nodes[sentinel].prev)
	}

	i := c.alloc()
	n := &c.nodes[i]
	n.key = key
	n.value = value
	c.index[key] = i
	c.pushFront(i)
}

// Get returns the value for key and reports whether it was present. A hit
// makes the key the most recently used.
func (c *Cache) Get(key string) (string, bool) {
	i, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.nodes[i].value, true
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.remove(i)
	return true
}

func (c *Cache) alloc() int32 {
	if n := len(c.free); n > 0 {
		i := c.free[n-1]
		c.free = c.free[:n-1]
		return i
	}
	c.nodes = append(c.nodes, node{})
	return int32(len(c.nodes) - 1)
}

func (c *Cache) remove(i int32) {
	n := &c.nodes[i]
	delete(c.index, n.key)
	c.unlink(i)
	*n = node{} // drop references so the strings can be collected
	c.free = append(c.free, i)
}

func (c *Cache) unlink(i int32) {
	n := &c.nodes[i]
	c.nodes[n.prev].next = n.next
	c.nodes[n.next].prev = n.prev
}

func (c *Cache) pushFront(i int32) {
	head := &c.nodes[sentinel]
	n := &c.nodes[i]
	n.prev = sentinel
	n.next = head.next
	c.nodes[head.next].prev = i
	head.next = i
}

func (c *Cache) moveToFront(i int32) {
	if c.nodes[sentinel].next == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

package lru

import "testing"

func TestEvictsLeastRecentlyUsed(t *testing.T) {
	c := New(2, 0)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v; want 1, true", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if got := c.Len(); got != 2 {
		t.Fatalf("Len() = %d; want 2", got)
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New(2, 0)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, ok := c.Get("a"); !ok || v != "9" {
		t.Fatalf("Get(a) = %q, %v; want 9, true", v, ok)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDeleteReusesSlots(t *testing.T) {
	c := New(3, 1)
	for round := 0; round < 3; round++ {
		c.Set("x", "1")
		c.Set("y", "2")
		if !c.Delete("x") || c.Delete("x") {
			t.Fatal("Delete(x) should succeed exactly once")
		}
		if !c.Delete("y") {
			t.Fatal("Delete(y) should succeed")
		}
		if c.Len() != 0 {
			t.Fatalf("Len() = %d; want 0", c.Len())
		}
	}
	if len(c.nodes) > 3 {
		t.Fatalf("pool grew to %d nodes; slots not reused", len(c.nodes))
	}
}

// Command app simulates an LRU cache driven by commands on standard input.
//
// The first line holds the capacity; each later line is one of
// SET <key> <value>, GET <key>, DEL <key> or SIZE. See SPEC.md.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"lru/internal/lru"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintf(os.Stderr, "lru: %v\n", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	data, err := io.ReadAll(r)
	if err != nil {
		return fmt.Errorf("read input: %w", err)
	}
	// One copy into a string lets keys and values be zero-copy substrings.
	input := string(data)

	first, rest := nextLine(input)
	capacity, ok := parseCapacity(first)
	if !ok {
		return nil // nothing to simulate
	}

	cache := lru.New(capacity, strings.Count(rest, "\n")+1)
	out := bufio.NewWriterSize(w, 64<<10)
	for rest != "" {
		var line string
		line, rest = nextLine(rest)
		execute(cache, line, out)
	}
	if err := out.Flush(); err != nil {
		return fmt.Errorf("write output: %w", err)
	}
	return nil
}

// nextLine splits off the first line of s, without its "\n" or a trailing "\r".
func nextLine(s string) (line, rest string) {
	line, rest, _ = strings.Cut(s, "\n")
	return strings.TrimSuffix(line, "\r"), rest
}

// nextToken splits off the next space-delimited token of s; tok is empty if
// none remain.
func nextToken(s string) (tok, rest string) {
	s = strings.TrimLeft(s, " ")
	if i := strings.IndexByte(s, ' '); i >= 0 {
		return s[:i], s[i:]
	}
	return s, ""
}

// parseCapacity reads a positive decimal capacity from the first token.
func parseCapacity(line string) (int, bool) {
	tok, _ := nextToken(line)
	if tok == "" || len(tok) > 18 {
		return 0, false
	}
	for i := 0; i < len(tok); i++ {
		if tok[i] < '0' || tok[i] > '9' {
			return 0, false
		}
	}
	v, err := strconv.Atoi(tok)
	if err != nil || v == 0 {
		return 0, false
	}
	return v, true
}

// execute runs one command line. Blank, malformed and unknown commands are
// ignored.
func execute(cache *lru.Cache, line string, out *bufio.Writer) {
	cmd, rest := nextToken(line)
	switch cmd {
	case "GET":
		key, _ := nextToken(rest)
		if key == "" {
			return
		}
		if v, ok := cache.Get(key); ok {
			out.WriteString(v)
		} else {
			out.WriteString("NULL")
		}
		out.WriteByte('\n')
	case "SET":
		key, rest := nextToken(rest)
		value, _ := nextToken(rest)
		if key == "" || value == "" {
			return
		}
		cache.Set(key, value)
	case "DEL":
		key, _ := nextToken(rest)
		if key == "" {
			return
		}
		if cache.Delete(key) {
			out.WriteString("1\n")
		} else {
			out.WriteString("0\n")
		}
	case "SIZE":
		var buf [20]byte
		out.Write(strconv.AppendInt(buf[:0], int64(cache.Len()), 10))
		out.WriteByte('\n')
	}
}
